package com.ethk3.novaonepro.strategyv2;

import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import com.ethk3.novaonepro.*;
import java.io.*;
import java.util.*;

/** Gap receipt reference producer. The original retention selection (keep 2048,
 * select at most 256) is fixed before preparation. CAS preparation commits one
 * item at a time outside the writer; applying at most 64 rows releases the
 * writer before the next chunk. The original phase advances only with the last
 * apply commit. No label, checkpoint, parameter or qualification is created. */
public final class GapReferenceR31 {
    private GapReferenceR31(){}
    public static final String SOURCE="r26_gap_receipt",ARCHIVE="r30_keep_"+SOURCE,MODE="REFERENCE_ONLY_GAP";
    public static final String VERSION="R31_GAP_REFERENCE_PRODUCER_1",COLUMNS="policy_hash,after_ordinal,before_ordinal,missing_count,reason,recorded_at";
    public static final int KEEP_ROWS=2048,ORIGINAL_PAGE=256,APPLY_ROWS=64,RUNTIME_PHASE=20;
    public static final String[] DDL={
        "CREATE TABLE IF NOT EXISTS r31_gap_reference_batch(batch_id TEXT PRIMARY KEY,retention_checkpoint TEXT,cycle_sequence INTEGER NOT NULL,source_schema_hash TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('PREPARING','READY','APPLYING','APPLIED')),expected_rows INTEGER NOT NULL CHECK(expected_rows BETWEEN 1 AND 256),prepared_rows INTEGER NOT NULL DEFAULT 0,applied_rows INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,finished_at INTEGER NOT NULL DEFAULT 0)",
        "CREATE TABLE IF NOT EXISTS r31_gap_reference_item(batch_id TEXT NOT NULL,ordinal INTEGER NOT NULL,source_rowid INTEGER NOT NULL,row_json TEXT NOT NULL,archive_id INTEGER NOT NULL,row_hash TEXT,state TEXT NOT NULL CHECK(state IN ('PENDING','PREPARED','APPLIED')),PRIMARY KEY(batch_id,ordinal),UNIQUE(batch_id,source_rowid))",
        "CREATE INDEX IF NOT EXISTS idx_r31_gap_reference_pending ON r31_gap_reference_item(batch_id,state,ordinal)",
        "CREATE TABLE IF NOT EXISTS r31_gap_reference_permit(source_rowid INTEGER PRIMARY KEY,batch_id TEXT NOT NULL,archive_id INTEGER NOT NULL,row_hash TEXT NOT NULL,policy_hash TEXT NOT NULL,after_ordinal INTEGER NOT NULL,before_ordinal INTEGER NOT NULL,missing_count INTEGER NOT NULL,reason TEXT NOT NULL,recorded_at INTEGER NOT NULL)",
        "CREATE TABLE IF NOT EXISTS r31_gap_reference_original(archive_id INTEGER PRIMARY KEY,row_hash TEXT NOT NULL,policy_hash TEXT NOT NULL,after_ordinal INTEGER NOT NULL,before_ordinal INTEGER NOT NULL,missing_count INTEGER NOT NULL,original_recorded_at INTEGER NOT NULL,archived_at INTEGER NOT NULL)"
    };
    private static String q(String value){return ResearchRetentionStoreR30.q(value);}
    public static boolean ready(SQLiteDatabase db){try(Cursor c=db.rawQuery("SELECT count(*) FROM sqlite_master WHERE type='table' AND name IN ('r31_gap_reference_batch','r31_gap_reference_item','r31_gap_reference_permit','r31_gap_reference_original')",null)){return c.moveToFirst()&&c.getInt(0)==4;}}
    public static String mode(SQLiteDatabase db){return KeepArchiveRetirementR31.mode(db,SOURCE);}
    public static boolean active(SQLiteDatabase db){return ready(db)&&MODE.equals(mode(db));}
    public static String effectiveSchemaHash(SQLiteDatabase db,String source,String original){return SOURCE.equals(source)&&active(db)?"R31_GAP_REFERENCE_ONLY:"+original:original;}
    private static String same(String alias,String value){StringJoiner clauses=new StringJoiner(" AND ");for(String column:COLUMNS.split(","))clauses.add(alias+"."+q(column)+" IS "+value+"."+q(column));return clauses.toString();}
    private static void requireSourceContract(SQLiteDatabase db){String expected=null;for(String sql:RuntimeSchemaR26.DDL)if(sql.startsWith("CREATE TABLE IF NOT EXISTS "+SOURCE+"("))expected="CREATE TABLE "+sql.substring("CREATE TABLE IF NOT EXISTS ".length());try(Cursor c=db.rawQuery("SELECT sql FROM sqlite_master WHERE type='table' AND name=?",new String[]{SOURCE})){if(expected==null||!c.moveToFirst()||!expected.equals(c.getString(0).trim()))throw new DatabaseCoordinator.SchemaPendingR31(VERSION,"GAP_SOURCE_COLUMNS_OR_TYPES_CHANGED");}}
    private static String originalSchemaHash(){String[] names=COLUMNS.split(","),types={"TEXT","INTEGER","INTEGER","INTEGER","TEXT","INTEGER"};List<List<String>> columns=new ArrayList<>();for(int i=0;i<names.length;i++)columns.add(Arrays.asList(names[i],types[i],i<3?Integer.toString(i+1):"0"));return StatsR27.sha256(JsonR27.write(columns));}
    private static String enabled(){return "(EXISTS(SELECT 1 FROM r31_keep_cutover WHERE source_table='"+SOURCE+"' AND mode='"+MODE+"') OR NOT EXISTS(SELECT 1 FROM r30_retention_archive_index WHERE source_table='"+SOURCE+"' AND schema_hash='"+originalSchemaHash()+"'))";}
    public static String[] guardDefinitionsR31(SQLiteDatabase db){
        if(!ResearchRetentionStoreR30.exists(db,SOURCE))return new String[0];
        String delete="CREATE TRIGGER IF NOT EXISTS r31_gap_reference_delete BEFORE DELETE ON "+SOURCE+" WHEN "+enabled()+" BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM r31_gap_reference_permit p JOIN r31_keep_original o ON o.archive_table='"+ARCHIVE+"' AND o.row_id=p.archive_id AND o.row_hash=p.row_hash AND o.state='PRODUCER_PREPARED' WHERE p.source_rowid=OLD.rowid AND "+same("p","OLD")+") THEN RAISE(ABORT,'R31_GAP_REFERENCE_PERMIT_REQUIRED') END; INSERT INTO r31_gap_reference_original SELECT p.archive_id,p.row_hash,OLD.policy_hash,OLD.after_ordinal,OLD.before_ordinal,OLD.missing_count,OLD.recorded_at,CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) FROM r31_gap_reference_permit p WHERE p.source_rowid=OLD.rowid; UPDATE r31_keep_original SET state='MIGRATED_ORIGINAL_RETAINED',migrated_at=CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) WHERE archive_table='"+ARCHIVE+"' AND row_id=(SELECT archive_id FROM r31_gap_reference_permit WHERE source_rowid=OLD.rowid); UPDATE r30_retention_archive_index SET retained_rows=retained_rows+1 WHERE source_table='"+SOURCE+"'; DELETE FROM r31_gap_reference_permit WHERE source_rowid=OLD.rowid; END";
        String update="CREATE TRIGGER IF NOT EXISTS r31_gap_reference_update BEFORE UPDATE ON "+SOURCE+" WHEN "+enabled()+" BEGIN SELECT RAISE(ABORT,'R31_GAP_RECEIPT_APPEND_ONLY'); END";
        String insert="CREATE TRIGGER IF NOT EXISTS r31_gap_reference_insert BEFORE INSERT ON "+SOURCE+" WHEN "+enabled()+" AND EXISTS(SELECT 1 FROM "+SOURCE+" WHERE policy_hash=NEW.policy_hash AND after_ordinal=NEW.after_ordinal AND before_ordinal=NEW.before_ordinal) BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM "+SOURCE+" prior WHERE prior.policy_hash=NEW.policy_hash AND prior.after_ordinal=NEW.after_ordinal AND prior.before_ordinal=NEW.before_ordinal AND "+same("prior","NEW")+") THEN RAISE(IGNORE) ELSE RAISE(ABORT,'R31_GAP_RECEIPT_INSERT_CONFLICT') END; END";
        return new String[]{delete,update,insert};
    }
    static LinkedHashMap<String,String> expectedGuards(SQLiteDatabase db,String source,LinkedHashMap<String,String> prior){
        if(!SOURCE.equals(source))return prior;if(active(db))requireSourceContract(db);LinkedHashMap<String,String> guards=new LinkedHashMap<>(prior);for(String ddl:guardDefinitionsR31(db)){String name=ddl.substring("CREATE TRIGGER IF NOT EXISTS ".length()).split(" ",2)[0];try(Cursor c=db.rawQuery("SELECT 1 FROM sqlite_master WHERE type='trigger' AND name=?",new String[]{name})){if(c.moveToFirst())guards.put(name,ddl);}}return guards;
    }
    /** Only a fully installed, authenticated generic original-reader cutover
     * can enter this separate production reference protocol. */
    public static boolean advanceCutoverWithinMigrationR31(SQLiteDatabase db){
        if(!db.inTransaction())throw new IllegalStateException("R31_GAP_REFERENCE_MIGRATION_WRITER_REQUIRED");if(!ready(db)||active(db)||!KeepArchiveRetirementR31.MODE.equals(mode(db))||KeepMismatchReferenceR31.authorityProof(db)==null)return false;
        requireSourceContract(db);for(String ddl:guardDefinitionsR31(db)){String name=ddl.substring("CREATE TRIGGER IF NOT EXISTS ".length()).split(" ",2)[0];ResearchRetentionStoreR30.requireGuardDefinitionsR31(db,new String[][]{{name,ddl}},true);}
        requireSourceContract(db);ResearchRetentionStoreR30.requireKeepMigrationSourceR31(db,ARCHIVE);if(KeepMigrationStoreR31.scalar(db,"SELECT count(*) FROM "+ARCHIVE)!=0)return false;
        String hash;try(Cursor c=db.rawQuery("SELECT schema_hash FROM r30_retention_archive_index WHERE source_table=?",new String[]{SOURCE})){if(!c.moveToFirst())return false;hash=c.getString(0);}
        db.execSQL("UPDATE r31_keep_cutover SET mode=?,producer_contract_hash=?,updated_at=? WHERE source_table=? AND mode=?",new Object[]{MODE,StatsR27.sha256(VERSION+"|KEEP=2048|PAGE=256|APPLY=64|RuntimeCoordinatorR26.retention-phase20|LivePoolR26.append"),System.currentTimeMillis(),SOURCE,KeepArchiveRetirementR31.MODE});
        db.execSQL("UPDATE r30_retention_archive_index SET schema_hash=? WHERE source_table=? AND schema_hash=?",new Object[]{"R31_GAP_REFERENCE_ONLY:"+hash,SOURCE,hash});if(KeepMigrationStoreR31.scalar(db,"SELECT changes()")!=1)throw new IllegalStateException("R31_GAP_REFERENCE_SWITCH_CAS");return true;
    }
    private static String batchId(RetentionR26.Checkpoint expected,long cycle){return StatsR27.sha256(VERSION+"|"+cycle+"|"+String.valueOf(expected.original));}
    private static void phaseFence(SQLiteDatabase db,RetentionR26.Checkpoint expected){if(!Objects.equals(expected.original,RetentionR26.checkpoint(db).original))throw new IllegalStateException("R31_GAP_RETENTION_PHASE_CHANGED");if(!active(db)||KeepMismatchReferenceR31.authorityProof(db)==null)throw new IllegalStateException("R31_GAP_REFERENCE_AUTHORITY_CHANGED");}
    /** Production entry before entering the old retention writer. Returns only
     * real committed work. The caller must not run the old phase18 DELETE too. */
    public static long advance(DbStore store,RuntimeCoordinatorR26.Claim claim,BudgetTokenSU1 budget,RetentionR26.Checkpoint expected,long cycle)throws IOException{
        KeepMigrationStoreR31.Writer writer=(operation,work)->store.coordinatorForResearchR952().runAtomicWriteOrThrowF01(DatabaseCoordinator.WriteContext.of(DatabaseCoordinator.WriteClass.RETENTION,operation),db->{RuntimeCoordinatorR26.requireFence(db,claim);work.run(db);RuntimeCoordinatorR26.requireFence(db,claim);return 0;});
        return advancePrepared(store.readable(),new File(store.contextForR26().getFilesDir(),"r31-keep"),writer,budget::checkpointOrYield,claim::reason,expected,cycle);
    }
    /** Same production engine exposed to native SQLite/file failure injection.
     * Writer/fence adapters do not duplicate any source selection or mutation. */
    @SuppressWarnings("unchecked") public static long advancePrepared(SQLiteDatabase read,File root,KeepMigrationStoreR31.Writer writer,Runnable check,java.util.function.Consumer<String> reason,RetentionR26.Checkpoint expected,long cycle)throws IOException{
        MemoryBudgetR31.Admission capacity=MemoryBudgetR31.processBudget().tryAcquire("gap-reference-producer",MemoryBudgetR31.Kind.CHECKPOINT,8L<<20,()->Thread.currentThread().isInterrupted());if(!capacity.acquired())throw new MemoryBudgetR31.CapacityWait(capacity.reason);
        try(MemoryBudgetR31.Lease memory=capacity.lease){
        requireSourceContract(read);if(expected.phase!=RUNTIME_PHASE)throw new IllegalArgumentException("R31_GAP_REFERENCE_WRONG_PHASE");if(!active(read))throw new DatabaseCoordinator.SchemaPendingR31(VERSION,"REFERENCE_PROTOCOL_NOT_ACTIVE");check.run();String id=batchId(expected,cycle);String state=null;long created=0;
        try(Cursor c=read.rawQuery("SELECT state,created_at FROM r31_gap_reference_batch WHERE batch_id=?",new String[]{id})){if(c.moveToFirst()){state=c.getString(0);created=c.getLong(1);}}
        if(state==null){
            try(Cursor size=read.rawQuery("SELECT coalesce(sum(bytes),0),coalesce(max(bytes),0) FROM (SELECT length(CAST(reason AS BLOB)) AS bytes FROM "+SOURCE+" ORDER BY recorded_at DESC,rowid DESC LIMIT 256 OFFSET 2048)",null)){if(!size.moveToFirst()||size.getLong(0)>1048576||size.getLong(1)>262144)throw new MemoryBudgetR31.CapacityWait(MemoryBudgetR31.WaitReason.DECLARED_CAPACITY);}
            List<Object[]> rows=new ArrayList<>();try(Cursor c=read.rawQuery("SELECT rowid,"+COLUMNS+" FROM "+SOURCE+" ORDER BY recorded_at DESC,rowid DESC LIMIT 256 OFFSET 2048",null)){while(c.moveToNext()){check.run();Object[] row=KeepMigrationStoreR31.values(c);if(((String)row[5]).length()>262144)throw new MemoryBudgetR31.CapacityWait(MemoryBudgetR31.WaitReason.DECLARED_CAPACITY);rows.add(row);}}
            long at=System.currentTimeMillis();writer.write("R31_GAP_REFERENCE_PLAN",db->{phaseFence(db,expected);if(rows.isEmpty()){RetentionR26.commitCheckpoint(db,expected,cycle,null,-1);return;}
                String schema;try(Cursor c=db.rawQuery("SELECT schema_hash FROM r30_retention_archive_index WHERE source_table=?",new String[]{SOURCE})){if(!c.moveToFirst())throw new IllegalStateException("R31_GAP_SOURCE_SCHEMA_UNAVAILABLE");schema=c.getString(0);}
                db.execSQL("INSERT INTO r31_gap_reference_batch VALUES(?,?,?,?,'PREPARING',?,0,0,?,0)",new Object[]{id,expected.original,cycle,schema,rows.size(),at});int ordinal=0;
                for(Object[] row:rows){List<Object> original=Arrays.asList(Arrays.copyOfRange(row,1,row.length));String json=JsonR27.write(original);long originalId=-1-Long.parseLong(StatsR27.sha256(json).substring(0,15),16);db.execSQL("INSERT INTO r31_gap_reference_item VALUES(?,?,?,?,?,NULL,'PENDING')",new Object[]{id,ordinal++,row[0],json,originalId});}});reason.accept(rows.isEmpty()?"R31_GAP_REFERENCE_EMPTY_PHASE_COMMITTED":"R31_GAP_REFERENCE_PLAN_COMMITTED");return 1;
        }
        if(state.equals("PREPARING")){
            final long at=created;List<Object[]> pending=new ArrayList<>();try(Cursor c=read.rawQuery("SELECT ordinal,source_rowid,row_json,archive_id FROM r31_gap_reference_item WHERE batch_id=? AND state='PENDING' ORDER BY ordinal LIMIT 16",new String[]{id})){while(c.moveToNext())pending.add(KeepMigrationStoreR31.values(c));}
            int prepared=0;
            for(Object[] item:pending){check.run();Object[] row=((List<Object>)JsonR27.parse((String)item[2])).toArray();long archiveId=((Number)item[3]).longValue();Object[] original=new Object[row.length+3];original[0]=archiveId;original[1]=at;original[2]="BEFORE_ORIGINAL_DELETE";System.arraycopy(row,0,original,3,row.length);
                KeepMigrationStoreR31.Prepared file=KeepMigrationStoreR31.prepareValues(root,ARCHIVE,archiveId,("__r30_id,__r30_at,__r30_reason,"+COLUMNS).split(","),original);
                writer.write("R31_GAP_REFERENCE_PREPARE_ITEM",db->{phaseFence(db,expected);
                    try(Cursor c=db.rawQuery("SELECT "+COLUMNS+" FROM "+SOURCE+" WHERE rowid=?",new String[]{String.valueOf(item[1])})){if(!c.moveToFirst()||!Arrays.deepEquals(row,KeepMigrationStoreR31.values(c)))throw new IllegalStateException("R31_GAP_SOURCE_ITEM_CHANGED");}
                    db.execSQL("INSERT OR IGNORE INTO r31_keep_original VALUES(?,?,?,?,?,'PRODUCER_PREPARED',?,0)",new Object[]{ARCHIVE,archiveId,file.hash,file.bytes,"[]",System.currentTimeMillis()});try(Cursor c=db.rawQuery("SELECT row_hash,state FROM r31_keep_original WHERE archive_table=? AND row_id=?",new String[]{ARCHIVE,Long.toString(archiveId)})){if(!c.moveToFirst()||!file.hash.equals(c.getString(0))||!"PRODUCER_PREPARED".equals(c.getString(1)))throw new IllegalStateException("R31_GAP_PREPARED_ORIGINAL_CONFLICT");}
                    db.execSQL("UPDATE r31_gap_reference_item SET row_hash=?,state='PREPARED' WHERE batch_id=? AND ordinal=? AND state='PENDING' AND row_json=?",new Object[]{file.hash,id,item[0],item[2]});if(KeepMigrationStoreR31.scalar(db,"SELECT changes()")!=1)throw new IllegalStateException("R31_GAP_PREPARATION_CAS");db.execSQL("UPDATE r31_gap_reference_batch SET prepared_rows=prepared_rows+1 WHERE batch_id=? AND state='PREPARING'",new Object[]{id});});prepared++;
            }
            final long[] readyTransition={0};writer.write("R31_GAP_REFERENCE_READY",db->{phaseFence(db,expected);db.execSQL("UPDATE r31_gap_reference_batch SET state='READY' WHERE batch_id=? AND state='PREPARING' AND prepared_rows=expected_rows",new Object[]{id});readyTransition[0]=KeepMigrationStoreR31.scalar(db,"SELECT changes()");});reason.accept("R31_GAP_REFERENCE_CAS_ITEMS_COMMITTED:"+prepared+":READY_TRANSITIONS="+readyTransition[0]);return prepared+readyTransition[0];
        }
        if(state.equals("READY")||state.equals("APPLYING")){
            List<Object[]> items=new ArrayList<>();try(Cursor c=read.rawQuery("SELECT ordinal,source_rowid,row_json,archive_id,row_hash FROM r31_gap_reference_item WHERE batch_id=? AND state='PREPARED' ORDER BY ordinal LIMIT 64",new String[]{id})){while(c.moveToNext())items.add(KeepMigrationStoreR31.values(c));}
            for(Object[] item:items){check.run();KeepMigrationStoreR31.readArtifact(root,ARCHIVE,((Number)item[3]).longValue(),(String)item[4],"__r30_id");}
            writer.write("R31_GAP_REFERENCE_APPLY_PAGE",db->{phaseFence(db,expected);for(Object[] item:items){Object[] row=((List<Object>)JsonR27.parse((String)item[2])).toArray();if(KeepMigrationStoreR31.scalar(db,"SELECT count(*) FROM (SELECT rowid FROM "+SOURCE+" ORDER BY recorded_at DESC,rowid DESC LIMIT 2048) WHERE rowid=?",String.valueOf(item[1]))!=0)throw new IllegalStateException("R31_GAP_PROTECTED_TAIL_CHANGED");Object[] permit=new Object[10];permit[0]=item[1];permit[1]=id;permit[2]=item[3];permit[3]=item[4];System.arraycopy(row,0,permit,4,row.length);db.execSQL("INSERT INTO r31_gap_reference_permit VALUES(?,?,?,?,?,?,?,?,?,?)",permit);db.execSQL("DELETE FROM "+SOURCE+" WHERE rowid=?",new Object[]{item[1]});if(KeepMigrationStoreR31.scalar(db,"SELECT changes()")!=1)throw new IllegalStateException("R31_GAP_REFERENCE_DELETE_CAS");db.execSQL("UPDATE r31_gap_reference_item SET state='APPLIED',row_json='' WHERE batch_id=? AND ordinal=? AND state='PREPARED' AND row_hash=?",new Object[]{id,item[0],item[4]});if(KeepMigrationStoreR31.scalar(db,"SELECT changes()")!=1)throw new IllegalStateException("R31_GAP_REFERENCE_ITEM_APPLY_CAS");}
                db.execSQL("UPDATE r31_gap_reference_batch SET applied_rows=applied_rows+?,state='APPLYING' WHERE batch_id=? AND state IN ('READY','APPLYING')",new Object[]{items.size(),id});if(KeepMigrationStoreR31.scalar(db,"SELECT changes()")!=1)throw new IllegalStateException("R31_GAP_REFERENCE_BATCH_APPLY_CAS");
                if(KeepMigrationStoreR31.scalar(db,"SELECT count(*) FROM r31_gap_reference_batch WHERE batch_id=? AND applied_rows=expected_rows",id)==1){db.execSQL("UPDATE r31_gap_reference_batch SET state='APPLIED',finished_at=? WHERE batch_id=?",new Object[]{System.currentTimeMillis(),id});RetentionR26.commitCheckpoint(db,expected,cycle,null,-1);}reason.accept("R31_GAP_REFERENCE_SOURCE_ROWS_COMMITTED:"+items.size());});return items.size();
        }
        throw new IllegalStateException("R31_GAP_REFERENCE_PHASE_DID_NOT_ADVANCE_WITH_APPLIED_BATCH");
        }
    }
    public static Map<String,Object> report(SQLiteDatabase db){Map<String,Object> out=new LinkedHashMap<>();out.put("version",VERSION);out.put("readOnly",true);out.put("source",SOURCE);out.put("mode",mode(db));out.put("retentionTargetRows",KEEP_ROWS);out.put("actualActiveSourceRows",ResearchRetentionStoreR30.exists(db,SOURCE)?KeepMigrationStoreR31.scalar(db,"SELECT count(*) FROM "+SOURCE):null);out.put("originalSelectionLimit",ORIGINAL_PAGE);out.put("writerApplyPage",APPLY_ROWS);out.put("naturalQuality","NOT_PROVEN_BY_STORAGE_WORK");if(!ready(db)){out.put("state","SCHEMA_PENDING");return out;}List<Object> batches=new ArrayList<>();try(Cursor c=db.rawQuery("SELECT batch_id,cycle_sequence,state,expected_rows,prepared_rows,applied_rows,created_at,finished_at FROM r31_gap_reference_batch ORDER BY created_at DESC,batch_id LIMIT 32",null)){while(c.moveToNext()){Map<String,Object> row=new LinkedHashMap<>();row.put("batchId",c.getString(0));row.put("cycleSequence",c.getLong(1));row.put("state",c.getString(2));row.put("selectedRows",c.getLong(3));row.put("casPreparedRows",c.getLong(4));row.put("sourceRowsActuallyArchived",c.getLong(5));row.put("createdAt",c.getLong(6));row.put("finishedAt",c.getLong(7));batches.add(row);}}out.put("batches",batches);out.put("state",active(db)?"PRODUCTION_REFERENCE_PROTOCOL_ACTIVE":"WAIT_OWNER_CUTOVER");out.put("executionState",batches.isEmpty()?"NOT_RUN_NO_ELIGIBLE_BATCH_OBSERVED":"ACTUAL_PERSISTED_BATCH_STATES");out.put("persistedOriginalReferences",KeepMigrationStoreR31.scalar(db,"SELECT count(*) FROM r31_gap_reference_original"));return out;}

}
